package greeter

import "strings"

// Slug 把一段文本转成小写、以单个连字符分隔的 slug。
// 首尾与连续空白会被归一化掉。
func Slug(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := map[string]string{
		"Hello World":     "hello-world",
		"  Hello World  ": "hello-world",
		"a   b":           "a-b",
	}
	for in, want := range cases {
		if got := Slug(in); got != want {
			t.Errorf("Slug(%q) = %q, want %q", in, got, want)
		}
	}
}

package greeter

import "strings"

// JoinSlug 依次把每个非空白片段转成 slug，再用 "/" 串起来。
// 空串与纯空白片段会被跳过。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, part := range parts {
		if strings.TrimSpace(part) == "" {
			continue
		}
		slugs = append(slugs, Slug(part))
	}
	return strings.Join(slugs, "/")
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	if got := JoinSlug("Hello World", "Big Day"); got != "hello-world/big-day" {
		t.Errorf("JoinSlug(Hello World, Big Day) = %q", got)
	}
	if got := JoinSlug("a", "", "b"); got != "a/b" {
		t.Errorf("JoinSlug(a, empty, b) = %q", got)
	}
	if got := JoinSlug("a", "   ", "b"); got != "a/b" {
		t.Errorf("JoinSlug(a, blank, b) = %q", got)
	}
}
